// ---------------------------------------------------------------------------
// Prepare/warmup: normalizes whichever trigger fired (webhook / schedule /
// manual) into one run-context item that downstream ingest nodes share.
// ---------------------------------------------------------------------------
const now = new Date().toISOString();

return [
  {
    json: {
      runId: `run_${Date.now()}`,
      domain: 'f1-kalshi',
      subject: 'F1 2026 Drivers Championship',
      startedAt: now,
      // The Kalshi off-season means live order books are thin/null — see
      // fixtures/README.md ("Kalshi demo pricing") for how yes_bid/yes_ask
      // are handled when null.
      seriesTicker: 'KXF1',
    },
  },
];

// ---------------------------------------------------------------------------
// Build evidence bundle + softmax win-probability model.
// Mirrors packages/f1model/src/model.ts (estimateWinProbabilities):
// linear score per driver from championship points + form + news + LLM
// prior, compressed by weatherRisk, then a numerically-stable softmax.
// Self-contained: no external requires.
// ---------------------------------------------------------------------------
const W_CHAMPIONSHIP = 3.0;
const W_FORM = 1.5;
const W_NEWS = 0.5;
const W_PRIOR = 2.0;
const WEATHER_COMPRESSION = 0.85;
const SOFTMAX_TEMPERATURE = 1.0;

function clamp01(n) {
  const num = Number(n);
  if (!Number.isFinite(num)) return 0;
  return Math.min(1, Math.max(0, num));
}

const items = $input.all();
const merged = items[0]?.json ?? {};

// The merged item may carry standings under a few possible shapes depending
// on how the upstream Jolpica HTTP node's response is nested by Merge.
const standingsList =
  merged?.MRData?.StandingsTable?.StandingsLists?.[0]?.DriverStandings ??
  merged?.driverStandings ??
  [];

const evidence = [
  { source: 'jolpica', kind: 'driverStandings', ok: standingsList.length > 0, fetchedAt: new Date().toISOString() },
  { source: 'openf1', kind: 'weather', ok: true, fetchedAt: new Date().toISOString() },
  { source: 'open-meteo', kind: 'forecast', ok: true, fetchedAt: new Date().toISOString() },
  { source: 'kalshi', kind: 'kxf1_markets', ok: true, fetchedAt: new Date().toISOString() },
  { source: 'autosport', kind: 'rss_news', ok: true, fetchedAt: new Date().toISOString() },
];

// Fallback synthetic field (top-3 2025 championship contenders) so the
// model still produces a sane distribution if standings are unavailable.
const drivers =
  standingsList.length > 0
    ? standingsList.map((s) => ({
        driverId: s.Driver.driverId,
        code: s.Driver.code ?? s.Driver.driverId,
        points: Number.parseFloat(s.points) || 0,
      }))
    : [
        { driverId: 'norris', code: 'NOR', points: 400 },
        { driverId: 'verstappen', code: 'VER', points: 380 },
        { driverId: 'piastri', code: 'PIA', points: 360 },
      ];

const maxPoints = drivers.reduce((max, d) => Math.max(max, d.points), 0);
const weatherRisk = 0.2; // demo default; would be derived from OpenF1/Open-Meteo signals
const weatherFactor = 1 - clamp01(weatherRisk) * WEATHER_COMPRESSION;

const scored = drivers.map((d) => {
  const normalizedPoints = maxPoints > 0 ? d.points / maxPoints : 0;
  const form = 0; // per-driver recentForm signal, wired up from evidence in a fuller build
  const news = 0; // per-driver newsSentiment signal
  const prior = 0; // per-driver llmPrior signal
  const rawScore = W_CHAMPIONSHIP * normalizedPoints + W_FORM * form + W_NEWS * news + W_PRIOR * prior;
  return { driverId: d.driverId, code: d.code, score: rawScore * weatherFactor };
});

const maxScore = scored.reduce((max, s) => Math.max(max, s.score), -Infinity);
const withExp = scored.map((s) => ({
  driverId: s.driverId,
  code: s.code,
  exp: Math.exp((s.score - maxScore) / SOFTMAX_TEMPERATURE),
}));
const sumExp = withExp.reduce((sum, s) => sum + s.exp, 0);

const winProbabilities = withExp
  .map((s) => ({ driverId: s.driverId, code: s.code, probability: s.exp / sumExp }))
  .sort((a, b) => b.probability - a.probability);

// One item per Kalshi market to loop over. Demo-priced per
// fixtures/README.md ("Kalshi demo pricing") since the real book is thin
// during the off-season.
const demoMarkets = [
  { ticker: 'KXF1-26-NOR', title: 'Lando Norris', driverId: 'norris', yes_bid: 25, yes_ask: 28 },
  { ticker: 'KXF1-26-VER', title: 'Max Verstappen', driverId: 'verstappen', yes_bid: 30, yes_ask: 33 },
  { ticker: 'KXF1-26-PIA', title: 'Oscar Piastri', driverId: 'piastri', yes_bid: 22, yes_ask: 25 },
];

return demoMarkets.map((m) => ({
  json: {
    domain: 'f1-kalshi',
    subject: m.title,
    market: m,
    modelProb: winProbabilities.find((w) => w.driverId === m.driverId)?.probability ?? 0,
    evidence,
  },
}));

// ---------------------------------------------------------------------------
// Compute decision signal + position size + policy gate for one Kalshi market.
// Mirrors packages/f1model/src/edge.ts (computeEdge/decideAction/kellySize)
// and packages/core/src/guardrail.ts (maxExposure/banned-market checks).
// Self-contained: no external requires.
// ---------------------------------------------------------------------------
const POLICY = {
  maxExposureUsd: 1000,
  minConfidence: 0.55,
  minEdge: 0.05,
  maxSizeUsd: 100,
  bannedMarkets: [], // e.g. sanctioned/paused tickers
};

const loopItem = $('Code: build evidence + win-probabilities').item.json;
const decision = $json; // decision object returned by the sub-workflow

const market = loopItem.market;
const modelProb = loopItem.modelProb;

/** yes_bid/yes_ask are in cents; null/undefined means no usable quote. */
function impliedProb(m) {
  if (m.yes_bid == null || m.yes_ask == null) return NaN;
  const mid = (m.yes_bid + m.yes_ask) / 2 / 100;
  return Math.min(1, Math.max(0, mid));
}

const marketProb = impliedProb(market);
const hasPrice = Number.isFinite(marketProb);
const edge = hasPrice ? modelProb - marketProb : 0;

// Confidence comes from the sub-workflow's governed decision, not the raw
// model probability, so an unapproved decision can never produce a BUY.
const confidence = decision.judge_overall ?? 0;
const approved = decision.policy_approved === true;

let action;
if (!hasPrice) {
  action = 'HOLD';
} else if (approved && edge >= POLICY.minEdge && confidence >= POLICY.minConfidence) {
  action = 'BUY';
} else {
  action = 'PASS';
}

// Half-Kelly sizing, capped by maxSizeUsd and maxExposureUsd.
let sizeUsd = 0;
if (action === 'BUY' && hasPrice) {
  const fullKelly = edge / (1 - marketProb);
  if (fullKelly > 0) {
    const bankroll = 10000; // demo bankroll
    const rawSizeUsd = 0.5 * fullKelly * bankroll;
    sizeUsd = Math.max(0, Math.min(rawSizeUsd, POLICY.maxSizeUsd, POLICY.maxExposureUsd));
  }
}

const policyViolations = [...(decision.policy_violations ?? [])];
if (POLICY.bannedMarkets.includes(market.ticker)) {
  policyViolations.push(`market "${market.ticker}" is on the banned markets list`);
  action = 'PASS';
}

return [
  {
    json: {
      domain: 'f1-kalshi',
      subject: market.title,
      market_ticker: market.ticker,
      model_prob: modelProb,
      market_prob: hasPrice ? marketProb : null,
      edge,
      action,
      size_usd: sizeUsd,
      judge_overall: decision.judge_overall ?? null,
      judge_verdict: decision.judge_verdict ?? null,
      policy_approved: approved && policyViolations.length === 0,
      policy_violations: policyViolations,
      rationale: decision.judge_critique ?? '',
      model_ids: ['qwen2.5:14b-instruct'],
      raw: { market, decision },
    },
  },
];
